{
  "rules": [
    {
      "category": "algorithmic_rent_setting",
      "title": "San Diego Prohibition of Algorithmic Rent Price-Fixing",
      "requirement": "Landlords are prohibited from using an algorithmic device that relies on nonpublic competitor data to set rental rates or occupancy levels, and persons are barred from selling or licensing such devices to landlords.",
      "requirement_es": "Se prohíbe a los propietarios usar dispositivos algorítmicos basados en datos no públicos de competidores para fijar tarifas de alquiler o niveles de ocupación, y se prohíbe vender o licenciar dichos dispositivos a propietarios.",
      "key_value": {
        "label": "algorithmic rent setting",
        "value": "prohibited"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Software or product used by a person to establish rental rates or income limits in accordance with local, state, or federal affordable housing program guidelines",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "software or product used by a person to establish rental rates or income limits in accordance with local, state, or federal affordable housing program guidelines"
              }
            ]
          }
        },
        {
          "description": "Software or products publishing aggregated historical reports (>90 days old) or using general public info without recommending future rates, or software used for appraisals not recommending rates during runtime",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2025-06-21",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": "The remedies under section 98.1104 are cumulative and are in addition to any other remedies in this Division or at law, statute, or ordinance."
      },
      "penalty": "Injunctive relief, damages, or civil penalties of up to $1,000 per violation (each month and each residential rental property constitutes a separate violation), plus costs and reasonable attorney's fees; City enforcement under Chapter 1, Article 2 including civil and criminal remedies.",
      "source_citation": "San Diego Mun. Code §§ 98.1101-98.1104",
      "quote": {
        "chunk": "c4",
        "start_words": "It is unlawful for a person",
        "end_words": "residential rental property."
      },
      "confidence": 0.98
    }
  ]
}
